import type { DungeonId } from '../../core/GameState';
import type { BossId, ThemeId } from '../../world/DungeonMap';

/**
 * Side-scrolling stages: 13 rows of 16x16 tiles under the 32px status bar.
 *   .  air            #  ground          =  one-way platform   C  crumbling block
 *   ^  spikes         ~  deadly mire     P  start              G  goal gate
 *   J  jar (drops an item)               F  fire-spitting stone lantern
 *   enemies: g ghoul  w wisp  c crow  k skeleton  b bat  h hopper
 *            r wraith  s spearman  o one-eye  n oni
 * Maps are generated by a segment script and checked for reachability (tests/stages.test.ts).
 */
export type StageId = 's1' | 's2' | 's3' | 's4';

export interface StageDef {
  title: string;
  subtitle: string;
  theme: ThemeId;
  map: string[];
  leadsTo: { kind: 'dungeon'; id: DungeonId } | { kind: 'boss'; boss: BossId };
}

